    { code: 'Q', kind: 'quarterly', rank: 5, flag: 'craa5_quarterly' }, { code: 'S', kind: 'semiannual', rank: 6, flag: 'craa5_month' },
    { code: 'A', kind: 'annual', rank: 7, flag: 'craa5_annually' }
